$db->exec('CREATE TABLE native_optional_guard_sources (id CHAR(32) NOT NULL PRIMARY KEY,club_id VARCHAR(64) NOT NULL,payload_json MEDIUMTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin');$source=bin2hex(random_bytes(16));Db::run($db,'INSERT INTO native_optional_guard_sources(id,club_id,payload_json) VALUES(?,?,?)',[$source,'synthetic-a','{"title":"Original retained unrelated source"}']);
$tables=$db->query("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_TYPE='BASE TABLE' ORDER BY TABLE_NAME")->fetchAll(PDO::FETCH_COLUMN);$before=ownOriginalDatabaseHash($db,$tables);$counts=[];foreach($tables as$table)$counts[$table]=(int)Db::run($db,'SELECT COUNT(*) FROM `'.$table.'`')->fetchColumn();$pixels=[];$files=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root.'/media',FilesystemIterator::SKIP_DOTS));foreach($files as$file)if($file->isFile())$pixels[$file->getPathname()]=hash_file('sha256',$file->getPathname());$isolation=$db->query('SELECT @@SESSION.transaction_isolation')->fetchColumn();
$n=0;$check=static function(bool $ok,string $label)use(&$n):void{if(!$ok)throw new RuntimeException($label);$n++;echo 'PASS '.$label."\n";};$denied=static function(callable $fn,string $label)use($check):void{try{$fn();}catch(DomainException|InvalidArgumentException){$check(true,$label);return;}throw new RuntimeException($label);};
try{
