    foreach(['reader','editor','outsider']as$actor)$denied(fn()=>(new MediaRemovalGuard($db,new Access($db,$actor)))->run($free['id'],fn()=>true),'current authority and own club are required for a guarded change');foreach(['',str_repeat('f',32),'../'.$free['id']]as$id)$denied(fn()=>$guard->run($id,fn()=>true),'malformed and missing originals never reach the guarded change');
    $db->beginTransaction();$denied(fn()=>$guard->run($free['id'],fn()=>true),'guard refuses an inherited transaction with an unknown earlier snapshot');$check($db->inTransaction(),'rejecting an inherited transaction leaves its owner in control');$db->rollBack();
    file_put_contents($root.'/control.json',json_encode(['id'=>$free['id'],'source'=>$source],JSON_THROW_ON_ERROR));chmod($root.'/control.json',0600);
    $committedId=bin2hex(random_bytes(16));$result=$guard->run($free['id'],function(array $asset)use($db,$free,$root,$check,$committedId):array{
        $check($db->inTransaction()&&$asset['id']===$free['id']&&$asset['sha256']===$free['sha256'],'guarded callback receives the exact freshly locked own original');
        foreach(['social','insert','update']as$case){$process=proc_open([...TestSupport::phpCommand(),__FILE__,'--concurrent',$case],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($process))throw new RuntimeException('Own concurrent PHP required.');fclose($pipes[0]);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($process);$state=json_decode($out,true);$check($exit===0&&$err===''&&$state===['blocked'=>true,'lock_wait'=>true],'actual independent '.$case.' writer cannot add a source between check and commit');}
        Db::run($db,'INSERT INTO native_optional_guard_sources(id,club_id,payload_json) VALUES(?,?,?)',[$committedId,'synthetic-a','{"Own committed isolated change":true}']);
        return ['own_original'=>$asset['id']];
