    $check(!$references->inspect($free['id'])['referenced'],'earlier read only observation sees the actual original empty state');$lateId=bin2hex(random_bytes(16));Db::run($db,'INSERT INTO native_optional_guard_sources(id,club_id,payload_json) VALUES(?,?,?)',[$lateId,'synthetic-a',json_encode(['actual_new_reference'=>$free['id']],JSON_THROW_ON_ERROR)]);$denied(fn()=>$guard->run($free['id'],fn()=>true),'fresh guarded check rejects a real source added after an earlier empty observation');
    // Keep every earlier source intact and add a separate malformed original for the other free asset.
    $new=$media->upload($root.'/source.png','Own later free.png','Exact later original');$bad=bin2hex(random_bytes(16));Db::run($db,'INSERT INTO native_optional_guard_sources(id,club_id,payload_json) VALUES(?,?,?)',[$bad,'synthetic-a','{Own retained unparseable original']);$denied(fn()=>$guard->run($new['id'],fn()=>true),'incomplete source inspection never invokes a guarded change');
    $filter=static function(string $table)use($lateId,$bad,$new,$committedId):array{return match($table){'native_optional_guard_sources'=>[' WHERE id NOT IN (?,?,?)',[$lateId,$bad,$committedId]],'khcms_media'=>[' WHERE id<>?',[$new['id']]],default=>['',[]]};};$check(ownOriginalDatabaseHash($db,$tables,$filter)===$before,'every earlier complete source, account, publication and pixel record remains unchanged');foreach($counts as$table=>$count)$check((int)Db::run($db,'SELECT COUNT(*) FROM `'.$table.'`')->fetchColumn()===$count+match($table){'native_optional_guard_sources'=>3,'khcms_media'=>1,default=>0},'complete original table count plus exact new own retained controls: '.$table);foreach($pixels as$path=>$hash)$check(hash_file('sha256',$path)===$hash,'every earlier original photo variant remains byte identical');
    $check(!$db->inTransaction()&&$db->query('SELECT @@SESSION.transaction_isolation')->fetchColumn()===$isolation,'all rejected changes release their own locks and retain normal connection isolation');
